// Helper functions for metadata retrieval
function getSubjectById(subjectId) {
    return subjectsConfig.find(s => s.id === subjectId);
}

function getTopicById(subjectId, topicId) {
    const sub = getSubjectById(subjectId);
    return sub?.topics.find(t => t.id === topicId);
}

function getSubtopicById(subjectId, topicId, subtopicId) {
    const topic = getTopicById(subjectId, topicId);
    return topic?.subtopics.find(st => st.id === subtopicId);
}

function findSubtopicGlobal(subtopicId) {
    for (const sub of subjectsConfig) {
        for (const topic of sub.topics) {
            for (const st of topic.subtopics) {
                if (st.id === subtopicId) {
                    return { subject: sub, topic: topic, subtopic: st };
                }
            }
        }
    }
    return null;
}
